        'c' => hcl_to_json(input),
        _ => JsonValue::Null,
    }
}

fn yaml_to_json(input: &str) -> JsonValue {
    match serde_yaml::from_str::<YamlValue>(input) {
        Ok(yaml_val) => yaml_value_to_json(yaml_val),
        Err(_) => JsonValue::Null,
    }
}

fn yaml_value_to_json(val: YamlValue) -> JsonValue {
    match val {
        YamlValue::Null => JsonValue::Null,
        YamlValue::Bool(b) => JsonValue::Bool(b),
        YamlValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                JsonValue::Number(serde_json::Number::from(i))
            } else if let Some(u) = n.as_u64() {
                JsonValue::Number(serde_json::Number::from(u))
            } else if let Some(f) = n.as_f64() {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        JsonValue::String("Infinity".to_string())
                    } else {
                        JsonValue::String("-Infinity".to_string())
                    }
                } else if f.is_nan() {
                    JsonValue::String("NaN".to_string())
                } else {
                    serde_json::Number::from_f64(f)
                        .map(JsonValue::Number)
                        .unwrap_or(JsonValue::Null)
                }
            } else {
                JsonValue::Null
            }
        }
        YamlValue::String(s) => JsonValue::String(s),
        YamlValue::Sequence(seq) => {
            let arr: Vec<JsonValue> = seq.into_iter()
                .map(|v| yaml_value_to_json(v))
                .collect();
            JsonValue::Array(arr)
        }
        YamlValue::Mapping(map) => {
            let mut obj = serde_json::Map::new();
            for (k, v) in map.iter() {
                let key = match k {
                    YamlValue::String(s) => s.clone(),
                    _ => k.to_string(),
                };
                obj.insert(key, yaml_value_to_json(v.clone()));
            }
            JsonValue::Object(obj)
        }
        _ => JsonValue::Null,
    }
}

fn toml_to_json(input: &str) -> JsonValue {
    match input.parse::<toml::Value>() {
        Ok(toml_val) => toml_value_to_json(toml_val),
        Err(_) => JsonValue::Null,
    }
}

fn toml_value_to_json(val: toml::Value) -> JsonValue {
    match val {
        toml::Value::Boolean(b) => JsonValue::Bool(b),
        toml::Value::Integer(i) => {
            JsonValue::Number(serde_json::Number::from(i))
        }
        toml::Value::Float(f) => {
            if f.is_infinite() {
                if f.is_sign_positive() {
                    JsonValue::String("Infinity".to_string())
                } else {
                    JsonValue::String("-Infinity".to_string())
                }
            } else if f.is_nan() {
                JsonValue::String("NaN".to_string())
            } else {
                serde_json::Number::from_f64(f)
                    .map(JsonValue::Number)
                    .unwrap_or(JsonValue::Null)
            }
        }
        toml::Value::String(s) => JsonValue::String(s),
        toml::Value::Array(arr) => {
            let json_arr: Vec<JsonValue> = arr.into_iter()
                .map(|v| toml_value_to_json(v))
                .collect();
            JsonValue::Array(json_arr)
        }
        toml::Value::Table(tbl) => {
            let mut obj = serde_json::Map::new();
            for (k, v) in tbl.iter() {
                obj.insert(k.clone(), toml_value_to_json(v.clone()));
            }
            JsonValue::Object(obj)
        }
        _ => JsonValue::Null,
    }
}

fn json_to_json(input: &str) -> JsonValue {
    match serde_json::from_str::<JsonValue>(input) {
        Ok(val) => val,
        Err(_) => JsonValue::Null,
    }
}

fn hcl_to_json(input: &str) -> JsonValue {
    match hcl::parse(input) {
        Ok(body) => hcl_body_to_json(body),
        Err(_) => JsonValue::Null,
    }
}

fn hcl_body_to_json(body: hcl::Body) -> JsonValue {
    let mut obj = serde_json::Map::new();

    for attr in body.attributes() {
        obj.insert(
            attr.key.to_string(),
            hcl_expression_to_json(&attr.expr),
        );
    }

    for block in body.blocks() {
        let key = format!("{}", block.identifier);
        let value = hcl_block_to_json(block);

        if obj.contains_key(&key) {
            // Handle multiple blocks with same name
            if let Some(JsonValue::Array(ref mut arr)) = obj.get_mut(&key) {
                arr.push(value);
            } else {
                let existing = obj.remove(&key).unwrap();
                obj.insert(key, JsonValue::Array(vec![existing, value]));
            }
        } else {
            obj.insert(key, value);
        }
    }

    JsonValue::Object(obj)
}

fn hcl_block_to_json(block: &hcl::Block) -> JsonValue {
    let mut obj = serde_json::Map::new();

    // Add labels as properties if they exist
    for (i, label) in block.labels.iter().enumerate() {
        obj.insert(format!("label_{}", i), JsonValue::String(label.to_string()));
    }

    // Add attributes
    for attr in block.body.attributes() {
        obj.insert(
            attr.key.to_string(),
            hcl_expression_to_json(&attr.expr),
        );
    }

    // Add nested blocks
    for nested in block.body.blocks() {
        let key = format!("{}", nested.identifier);
        let value = hcl_block_to_json(nested);

        if obj.contains_key(&key) {
            if let Some(JsonValue::Array(ref mut arr)) = obj.get_mut(&key) {
                arr.push(value);
            } else {
                let existing = obj.remove(&key).unwrap();
                obj.insert(key, JsonValue::Array(vec![existing, value]));
            }
        } else {
            obj.insert(key, value);
        }
    }

    JsonValue::Object(obj)
}

fn hcl_expression_to_json(expr: &hcl::Expression) -> JsonValue {
    use hcl::Expression;

    match expr {
        Expression::Null => JsonValue::Null,
        Expression::Bool(b) => JsonValue::Bool(*b),
        Expression::Number(n) => {
            if let Ok(i) = n.parse::<i64>() {
                JsonValue::Number(serde_json::Number::from(i))
            } else if let Ok(f) = n.parse::<f64>() {
                serde_json::Number::from_f64(f)
                    .map(JsonValue::Number)
                    .unwrap_or(JsonValue::Null)
            } else {
                JsonValue::Null
            }
        }
        Expression::String(s) => JsonValue::String(s.to_string()),
        Expression::Array(arr) => {
            let json_arr: Vec<JsonValue> = arr.iter()
                .map(|e| hcl_expression_to_json(e))
                .collect();
            JsonValue::Array(json_arr)
        }
        Expression::Object(obj) => {
            let mut json_obj = serde_json::Map::new();
            for (k, v) in obj.iter() {
                json_obj.insert(k.to_string(), hcl_expression_to_json(v));
            }
            JsonValue::Object(json_obj)
        }
        _ => JsonValue::Null,
    }
}

fn convert_value(
    value: JsonValue,
    _from_format: char,
    to_format: char,
    escape_html: bool,
    indent: bool,
    no_convert_special: bool,
    parse_keys: bool,
) -> String {
    match to_format {
        'j' => json_output(&value, escape_html, indent),
        'y' => yaml_output(&value, parse_keys),
        't' => toml_output(&value, indent, no_convert_special),
        'c' => hcl_output(&value),
        _ => String::new(),
    }
}

fn json_output(value: &JsonValue, escape_html: bool, indent: bool) -> String {
    if escape_html {
        if indent {
            serde_json::to_string_pretty(value).unwrap_or_default()
        } else {
            serde_json::to_string(value).unwrap_or_default()
        }
    } else {
        // Default JSON output without HTML escaping
        if indent {
            serde_json::to_string_pretty(value).unwrap_or_default()
        } else {
            serde_json::to_string(value).unwrap_or_default()
        }
    }
}

fn yaml_output(value: &JsonValue, _parse_keys: bool) -> String {
    let yaml_value = json_to_yaml_value(value);
    serde_yaml::to_string(&yaml_value).unwrap_or_default()
}

fn json_to_yaml_value(json: &JsonValue) -> YamlValue {
    match json {
        JsonValue::Null => YamlValue::Null,
        JsonValue::Bool(b) => YamlValue::Bool(*b),
        JsonValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                YamlValue::Number(serde_yaml::Number::from(i))
            } else if let Some(u) = n.as_u64() {
                YamlValue::Number(serde_yaml::Number::from(u))
            } else if let Some(f) = n.as_f64() {
                YamlValue::Number(serde_yaml::Number::from(f))
            } else {
                YamlValue::Null
            }
        }
        JsonValue::String(s) => YamlValue::String(s.clone()),
        JsonValue::Array(arr) => {
            let yaml_arr: Vec<YamlValue> = arr.iter()
                .map(|v| json_to_yaml_value(v))
                .collect();
            YamlValue::Sequence(yaml_arr)
        }
        JsonValue::Object(obj) => {
            let mut yaml_map = serde_yaml::Mapping::new();
            for (k, v) in obj.iter() {
                yaml_map.insert(
                    YamlValue::String(k.clone()),
                    json_to_yaml_value(v),
                );
            }
            YamlValue::Mapping(yaml_map)
        }
    }
}

fn toml_output(value: &JsonValue, indent: bool, no_convert_special: bool) -> String {
    let toml_value = json_to_toml_value(value, no_convert_special);
    if indent {
        toml::to_string_pretty(&toml_value).unwrap_or_default()
    } else {
        toml::to_string(&toml_value).unwrap_or_default()
    }
}

fn json_to_toml_value(json: &JsonValue, no_convert_special: bool) -> toml::Value {
    match json {
        JsonValue::Null => toml::Value::Boolean(false),
        JsonValue::Bool(b) => toml::Value::Boolean(*b),
        JsonValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                toml::Value::Integer(i)
            } else if let Some(u) = n.as_u64() {
                toml::Value::Integer(u as i64)
            } else if let Some(f) = n.as_f64() {
                toml::Value::Float(f)
            } else {
                toml::Value::String(n.to_string())
            }
        }
        JsonValue::String(s) => {
            // Check for special float values when not in no_convert_special mode
            if !no_convert_special {
                match s.as_str() {
                    "Infinity" => toml::Value::Float(f64::INFINITY),
                    "-Infinity" => toml::Value::Float(f64::NEG_INFINITY),
                    "NaN" => toml::Value::Float(f64::NAN),
                    _ => toml::Value::String(s.clone()),
                }
            } else {
                toml::Value::String(s.clone())
            }
        }
        JsonValue::Array(arr) => {
            let toml_arr: Vec<toml::Value> = arr.iter()
                .map(|v| json_to_toml_value(v, no_convert_special))
                .collect();
            toml::Value::Array(toml_arr)
        }
        JsonValue::Object(obj) => {
            let mut toml_tbl = toml::map::Map::new();
            for (k, v) in obj.iter() {
                toml_tbl.insert(k.clone(), json_to_toml_value(v, no_convert_special));
            }
            toml::Value::Table(toml_tbl)
        }
    }
}

fn hcl_output(value: &JsonValue) -> String {
    // Basic HCL output - convert JSON to HCL format
    format_json_as_hcl(value, 0)
}

fn format_json_as_hcl(value: &JsonValue, indent_level: usize) -> String {
    let indent = "  ".repeat(indent_level);
    let next_indent = "  ".repeat(indent_level + 1);

    match value {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::String(s) => format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"")),
        JsonValue::Array(arr) => {
            let items: Vec<String> = arr.iter()
                .map(|v| format_json_as_hcl(v, indent_level + 1))
                .collect();
            format!("[\n{}{}\n{}]", next_indent, items.join(&format!(",\n{}", next_indent)), indent)
        }
        JsonValue::Object(obj) => {
            let items: Vec<String> = obj.iter()
                .map(|(k, v)| {
                    format!("{}{} = {}", next_indent, k, format_json_as_hcl(v, indent_level + 1))
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join("\n"), indent)
        }
    }
}
