fn json_to_toml_value(json: &JsonValue, no_convert_special: bool) -> toml::Value {
    match json {
        JsonValue::Null => toml::Value::Boolean(false),
        JsonValue::Bool(b) => toml::Value::Boolean(*b),
        JsonValue::Number(n) => {
            if let Some(i) = n.as_i64() {
                toml::Value::Integer(i)
            } else if let Some(u) = n.as_u64() {
                toml::Value::Integer(u as i64)
            } else if let Some(f) = n.as_f64() {
                toml::Value::Float(f)
            } else {
                toml::Value::String(n.to_string())
            }
        }
        JsonValue::String(s) => {
            // Check for special float values when not in no_convert_special mode
            if !no_convert_special {
                match s.as_str() {
                    "Infinity" => toml::Value::Float(f64::INFINITY),
                    "-Infinity" => toml::Value::Float(f64::NEG_INFINITY),
                    "NaN" => toml::Value::Float(f64::NAN),
                    _ => toml::Value::String(s.clone()),
                }
            } else {
                toml::Value::String(s.clone())
            }
        }
        JsonValue::Array(arr) => {
            let toml_arr: Vec<toml::Value> = arr.iter()
                .map(|v| json_to_toml_value(v, no_convert_special))
                .collect();
            toml::Value::Array(toml_arr)
        }
        JsonValue::Object(obj) => {
            let mut toml_tbl = toml::map::Map::new();
            for (k, v) in obj.iter() {
                toml_tbl.insert(k.clone(), json_to_toml_value(v, no_convert_special));
            }
            toml::Value::Table(toml_tbl)
        }
    }
}

fn hcl_output(value: &JsonValue) -> String {
    // Basic HCL output - convert JSON to HCL format
    format_json_as_hcl(value, 0)
}

fn format_json_as_hcl(value: &JsonValue, indent_level: usize) -> String {
    let indent = "  ".repeat(indent_level);
    let next_indent = "  ".repeat(indent_level + 1);

    match value {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => b.to_string(),
        JsonValue::Number(n) => n.to_string(),
        JsonValue::String(s) => format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\"")),
        JsonValue::Array(arr) => {
            let items: Vec<String> = arr.iter()
                .map(|v| format_json_as_hcl(v, indent_level + 1))
                .collect();
            format!("[\n{}{}\n{}]", next_indent, items.join(&format!(",\n{}", next_indent)), indent)
        }
        JsonValue::Object(obj) => {
            let items: Vec<String> = obj.iter()
                .map(|(k, v)| {
                    format!("{}{} = {}", next_indent, k, format_json_as_hcl(v, indent_level + 1))
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join("\n"), indent)
        }
    }
}
