        Err(_) => JsonValue::Null,
    }
}

fn hcl_body_to_json(body: hcl::Body) -> JsonValue {
    let mut obj = serde_json::Map::new();

    for attr in body.attributes() {
        obj.insert(
            attr.key.to_string(),
            hcl_expression_to_json(&attr.expr),
        );
    }

    for block in body.blocks() {
        let key = format!("{}", block.identifier);
        let value = hcl_block_to_json(block);

        if obj.contains_key(&key) {
            // Handle multiple blocks with same name
            if let Some(JsonValue::Array(ref mut arr)) = obj.get_mut(&key) {
                arr.push(value);
            } else {
                let existing = obj.remove(&key).unwrap();
                obj.insert(key, JsonValue::Array(vec![existing, value]));
            }
        } else {
            obj.insert(key, value);
        }
    }

    JsonValue::Object(obj)
}

fn hcl_block_to_json(block: &hcl::Block) -> JsonValue {
    let mut obj = serde_json::Map::new();

    // Add labels as properties if they exist
    for (i, label) in block.labels.iter().enumerate() {
        obj.insert(format!("label_{}", i), JsonValue::String(label.to_string()));
    }

    // Add attributes
    for attr in block.body.attributes() {
        obj.insert(
            attr.key.to_string(),
            hcl_expression_to_json(&attr.expr),
        );
    }

    // Add nested blocks
    for nested in block.body.blocks() {
        let key = format!("{}", nested.identifier);
        let value = hcl_block_to_json(nested);

        if obj.contains_key(&key) {
            if let Some(JsonValue::Array(ref mut arr)) = obj.get_mut(&key) {
                arr.push(value);
            } else {
                let existing = obj.remove(&key).unwrap();
                obj.insert(key, JsonValue::Array(vec![existing, value]));
            }
        } else {
            obj.insert(key, value);
        }
    }

    JsonValue::Object(obj)
}

fn hcl_expression_to_json(expr: &hcl::Expression) -> JsonValue {
