    match expr {
        Expression::Null => JsonValue::Null,
        Expression::Bool(b) => JsonValue::Bool(*b),
        Expression::Number(n) => {
            if let Ok(i) = n.parse::<i64>() {
                JsonValue::Number(serde_json::Number::from(i))
            } else if let Ok(f) = n.parse::<f64>() {
