use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Integer(i64),
    Float(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

impl Value {
    pub fn to_json(&self, escape_html: bool, indent: bool) -> String {
        if indent {
            self.to_json_pretty(0, escape_html)
        } else {
            self.to_json_compact(escape_html)
        }
    }

    fn to_json_compact(&self, escape_html: bool) -> String {
        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        "null".to_string()
                    } else {
                        "null".to_string()
                    }
                } else if f.is_nan() {
                    "null".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                let escaped = if escape_html {
                    s.replace('<', "\\u003c")
                     .replace('>', "\\u003e")
                     .replace('&', "\\u0026")
                } else {
                    s.clone()
                };
                format!("\"{}\"", 
                    escaped
                        .replace('\\', "\\\\")
                        .replace('"', "\\\"")
                        .replace('\n', "\\n")
                        .replace('\r', "\\r")
                        .replace('\t', "\\t")
                )
            }
            Value::Array(arr) => {
                let items: Vec<String> = arr.iter()
                    .map(|v| v.to_json_compact(escape_html))
                    .collect();
                format!("[{}]", items.join(","))
            }
            Value::Object(obj) => {
                let items: Vec<String> = obj.iter()
                    .map(|(k, v)| {
                        let key_json = format!("\"{}\"", 
                            k.replace('\\', "\\\\")
                             .replace('"', "\\\"")
                             .replace('\n', "\\n")
                             .replace('\r', "\\r")
                             .replace('\t', "\\t")
                        );
                        format!("{}:{}", key_json, v.to_json_compact(escape_html))
                    })
                    .collect();
                format!("{{{}}}", items.join(","))
            }
        }
    }

    fn to_json_pretty(&self, depth: usize, escape_html: bool) -> String {
        let indent_str = "  ".repeat(depth);
        let next_indent_str = "  ".repeat(depth + 1);

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    "null".to_string()
                } else if f.is_nan() {
                    "null".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                let escaped = if escape_html {
                    s.replace('<', "\\u003c")
                     .replace('>', "\\u003e")
                     .replace('&', "\\u0026")
                } else {
                    s.clone()
                };
                format!("\"{}\"", 
                    escaped
                        .replace('\\', "\\\\")
                        .replace('"', "\\\"")
                        .replace('\n', "\\n")
                        .replace('\r', "\\r")
                        .replace('\t', "\\t")
                )
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| format!("{}{}", next_indent_str, v.to_json_pretty(depth + 1, escape_html)))
                        .collect();
                    format!("[\n{}\n{}]", items.join(",\n"), indent_str)
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let items: Vec<String> = obj.iter()
                        .map(|(k, v)| {
                            let key_json = format!("\"{}\"", 
                                k.replace('\\', "\\\\")
                                 .replace('"', "\\\"")
                                 .replace('\n', "\\n")
                                 .replace('\r', "\\r")
                                 .replace('\t', "\\t")
                            );
                            format!("{}{}: {}", next_indent_str, key_json, v.to_json_pretty(depth + 1, escape_html))
                        })
                        .collect();
                    format!("{{\n{}\n{}}}", items.join(",\n"), indent_str)
                }
            }
        }
    }

    pub fn to_yaml(&self) -> String {
        format!("{}\n", self.to_yaml_internal(0, true))
    }

    fn to_yaml_internal(&self, depth: usize, root: bool) -> String {
        let indent_str = "  ".repeat(depth);

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        ".inf".to_string()
                    } else {
                        "-.inf".to_string()
                    }
                } else if f.is_nan() {
                    ".nan".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                if s.contains('\n') || s.contains('"') || s.contains(':') {
                    format!("'{}'", s.replace('\'', "''"))
                } else {
                    s.clone()
                }
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| format!("{}  - {}", if depth > 0 { indent_str.as_str() } else { "" }, v.to_yaml_internal(depth + 1, false)))
                        .collect();
                    items.join("\n")
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let mut items = Vec::new();
                    for (k, v) in obj.iter() {
                        let key = if root {
                            k.clone()
                        } else {
                            format!("{}{}", indent_str, k)
                        };
                        match v {
                            Value::Object(_) | Value::Array(_) => {
                                items.push(format!("{}:\n{}", key, v.to_yaml_internal(depth + 1, false)));
                            }
                            _ => {
                                items.push(format!("{}: {}", key, v.to_yaml_internal(depth, false)));
                            }
                        }
                    }
                    items.join("\n")
                }
            }
        }
    }

    pub fn to_toml(&self, indent: bool, no_convert_special: bool) -> String {
        self.to_toml_internal(0, indent, no_convert_special)
    }

    fn to_toml_internal(&self, depth: usize, indent: bool, no_convert_special: bool) -> String {
        let indent_str = if indent { "  ".repeat(depth) } else { "".to_string() };

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if !no_convert_special {
                        if f.is_sign_positive() {
                            "Infinity".to_string()
                        } else {
                            "-Infinity".to_string()
                        }
                    } else {
                        if f.is_sign_positive() {
                            "1.7976931348623157e+308".to_string()
                        } else {
                            "-1.7976931348623157e+308".to_string()
                        }
                    }
                } else if f.is_nan() {
                    if !no_convert_special {
                        "NaN".to_string()
                    } else {
                        "null".to_string()
                    }
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                format!("\"{}\"", 
                    s.replace('\\', "\\\\")
                     .replace('"', "\\\"")
                     .replace('\n', "\\n")
                     .replace('\r', "\\r")
                     .replace('\t', "\\t")
                )
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| v.to_toml_internal(depth + 1, indent, no_convert_special))
                        .collect();
                    if indent && items.len() > 1 {
                        let next_indent = "  ".repeat(depth + 1);
                        format!("[\n{}{}\n{}]", next_indent, items.join(&format!(",\n{}", next_indent)), indent_str)
                    } else {
                        format!("[{}]", items.join(", "))
                    }
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let mut items = Vec::new();
                    for (k, v) in obj.iter() {
                        items.push(format!("{} = {}", k, v.to_toml_internal(depth + 1, indent, no_convert_special)));
                    }
                    if indent && depth > 0 {
                        let next_indent = "  ".repeat(depth);
                        items.join(&format!("\n{}", next_indent))
                    } else {
                        items.join("\n")
                    }
                }
            }
        }
    }

    pub fn to_hcl(&self) -> String {
        self.to_hcl_internal(0)
    }

    fn to_hcl_internal(&self, depth: usize) -> String {
        let indent_str = "  ".repeat(depth);
        let next_indent = "  ".repeat(depth + 1);

