            }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }

        let num_str: String = self.input[start..self.pos].iter().collect();

        if is_float {
            if let Ok(f) = num_str.parse::<f64>() {
                return Value::Float(f);
            }
        } else {
            if let Ok(i) = num_str.parse::<i64>() {
                return Value::Integer(i);
            }
        }

        Value::Null
    }

    fn parse_bool(&mut self) -> Value {
        if self.pos + 4 <= self.input.len() {
            let word: String = self.input[self.pos..self.pos + 4].iter().collect();
            if word == "true" {
                self.pos += 4;
                return Value::Bool(true);
            }
        }

        if self.pos + 5 <= self.input.len() {
            let word: String = self.input[self.pos..self.pos + 5].iter().collect();
            if word == "false" {
                self.pos += 5;
                return Value::Bool(false);
            }
        }

        Value::Null
    }

    fn parse_null(&mut self) -> Value {
        if self.pos + 4 <= self.input.len() {
            let word: String = self.input[self.pos..self.pos + 4].iter().collect();
            if word == "null" {
                self.pos += 4;
                return Value::Null;
            }
        }
        Value::Null
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }
}
