use crate::value::Value;
use std::collections::BTreeMap;

pub fn parse(input: &str, parse_keys: bool) -> Value {
    let lines: Vec<&str> = input.lines().collect();
    let mut parser = YamlParser::new(&lines, parse_keys);
    parser.parse()
}

struct YamlParser<'a> {
    lines: &'a [&'a str],
    pos: usize,
    parse_keys: bool,
}

impl<'a> YamlParser<'a> {
    fn new(lines: &'a [&'a str], parse_keys: bool) -> Self {
        YamlParser {
            lines,
            pos: 0,
            parse_keys,
        }
    }

    fn parse(&mut self) -> Value {
        self.skip_empty_lines();
        if self.pos >= self.lines.len() {
            return Value::Null;
        }

        let indent = self.get_indent(self.pos);
        self.parse_node(indent)
    }

    fn parse_node(&mut self, parent_indent: usize) -> Value {
        self.skip_empty_lines();
        if self.pos >= self.lines.len() {
            return Value::Null;
        }

        let line = self.lines[self.pos];
        let indent = self.get_indent(self.pos);

        if indent < parent_indent {
            return Value::Null;
        }

        let content = line.trim();

        // Check if this is a list item
        if content.starts_with("- ") {
            return self.parse_list(parent_indent);
        }

        // Check if this is a mapping
        if content.contains(':') && !content.starts_with('#') {
            return self.parse_mapping(parent_indent);
        }

        // Parse as a scalar value
        self.pos += 1;
        self.parse_scalar(content)
    }

    fn parse_list(&mut self, parent_indent: usize) -> Value {
        let mut arr = Vec::new();

        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            let indent = self.get_indent(self.pos);

            if indent < parent_indent {
                break;
            }

            let content = line.trim();
            if content.starts_with("- ") {
                self.pos += 1;
                let item_content = &content[2..];

                if item_content.contains(':') {
                    let mut item_map = BTreeMap::new();
                    let key_val: Vec<&str> = item_content.splitn(2, ':').collect();
                    if key_val.len() == 2 {
                        let key = key_val[0].trim();
                        let value = self.parse_scalar(key_val[1].trim());
                        item_map.insert(key.to_string(), value);
                    }

                    // Parse nested items
                    while self.pos < self.lines.len() {
                        let next_line = self.lines[self.pos];
                        let next_indent = self.get_indent(self.pos);
                        let next_content = next_line.trim();

                        if next_indent <= parent_indent {
                            break;
                        }

                        if !next_content.starts_with("- ") && next_content.contains(':') {
                            self.pos += 1;
                            let key_val: Vec<&str> = next_content.splitn(2, ':').collect();
                            if key_val.len() == 2 {
                                let key = key_val[0].trim();
                                let value = self.parse_scalar(key_val[1].trim());
                                item_map.insert(key.to_string(), value);
                            }
                        } else {
                            break;
                        }
                    }

                    arr.push(Value::Object(item_map));
                } else {
                    arr.push(self.parse_scalar(item_content));
                }
            } else if indent > parent_indent {
                break;
            } else {
                break;
            }
        }

        Value::Array(arr)
    }

    fn parse_mapping(&mut self, parent_indent: usize) -> Value {
        let mut map = BTreeMap::new();

        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            let indent = self.get_indent(self.pos);

            if indent < parent_indent {
                break;
            }

            if indent > parent_indent {
                self.pos += 1;
                continue;
            }

            let content = line.trim();

            if content.is_empty() || content.starts_with('#') {
                self.pos += 1;
                continue;
            }

            if content.starts_with("- ") {
                break;
            }

            if let Some(colon_idx) = content.find(':') {
                let key = content[..colon_idx].trim();
                let value_part = content[colon_idx + 1..].trim();

                self.pos += 1;

                // Parse the key (attempt to parse as number if parse_keys is true)
                let key_str = if self.parse_keys {
                    key.to_string()
                } else {
                    key.to_string()
                };

                // Check if value is on next line (nested structure)
                if value_part.is_empty() {
                    if self.pos < self.lines.len() {
                        let next_indent = self.get_indent(self.pos);
                        if next_indent > parent_indent {
                            let value = self.parse_node(next_indent);
                            map.insert(key_str, value);
                        } else {
                            map.insert(key_str, Value::Null);
                        }
                    } else {
                        map.insert(key_str, Value::Null);
                    }
                } else {
                    let value = self.parse_scalar(value_part);
                    map.insert(key_str, value);
                }
            } else {
                self.pos += 1;
            }
        }

        Value::Object(map)
    }

    fn parse_scalar(&self, content: &str) -> Value {
        let content = content.trim();

        if content.is_empty() {
            return Value::Null;
        }

        if content == "null" || content == "~" {
            return Value::Null;
        }

        if content == "true" {
            return Value::Bool(true);
        }

        if content == "false" {
            return Value::Bool(false);
        }

        if content == ".inf" || content == ".Inf" || content == ".INF" {
            return Value::Float(f64::INFINITY);
        }

        if content == "-.inf" || content == "-.Inf" || content == "-.INF" {
            return Value::Float(f64::NEG_INFINITY);
        }

        if content == ".nan" || content == ".NaN" || content == ".NAN" {
            return Value::Float(f64::NAN);
        }

        // Try to parse as number
        if let Ok(i) = content.parse::<i64>() {
            return Value::Integer(i);
        }

        if let Ok(f) = content.parse::<f64>() {
            return Value::Float(f);
        }

        // Remove quotes if present
        let unquoted = if (content.starts_with('"') && content.ends_with('"')) ||
                          (content.starts_with('\'') && content.ends_with('\'')) {
            &content[1..content.len()-1]
        } else {
            content
        };

        Value::String(unquoted.to_string())
    }

    fn get_indent(&self, line_idx: usize) -> usize {
        if line_idx >= self.lines.len() {
            return 0;
        }
        let line = self.lines[line_idx];
        line.len() - line.trim_start().len()
    }

    fn skip_empty_lines(&mut self) {
        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            if line.trim().is_empty() || line.trim().starts_with('#') {
                self.pos += 1;
            } else {
                break;
            }
        }
    }
}
