use crate::value::Value;
use std::collections::BTreeMap;

pub fn parse(input: &str) -> Value {
    let mut parser = HclParser::new(input);
    parser.parse()
}

struct HclParser {
    input: String,
    pos: usize,
}

impl HclParser {
    fn new(input: &str) -> Self {
        HclParser {
            input: input.to_string(),
            pos: 0,
        }
    }

    fn parse(&mut self) -> Value {
        let mut map = BTreeMap::new();

        while self.pos < self.input.len() {
            self.skip_whitespace_and_comments();

            if self.pos >= self.input.len() {
                break;
            }

            // Try to parse a key = value
            if let Some(key) = self.parse_identifier() {
                self.skip_whitespace_and_comments();

                if self.peek() == Some('=') {
                    self.pos += 1;
                    let value = self.parse_value();
                    map.insert(key, value);
                } else if self.peek() == Some('{') {
                    // Block
                    self.pos += 1;
                    let block_content = self.parse_block_content();
                    map.insert(key, block_content);
                }
            } else {
                self.pos += 1;
            }
        }

        Value::Object(map)
    }

    fn parse_block_content(&mut self) -> Value {
        let mut map = BTreeMap::new();

        while self.pos < self.input.len() {
            self.skip_whitespace_and_comments();

            if self.peek() == Some('}') {
                self.pos += 1;
                break;
            }

            if let Some(key) = self.parse_identifier() {
                self.skip_whitespace_and_comments();

                if self.peek() == Some('=') {
                    self.pos += 1;
                    let value = self.parse_value();
                    map.insert(key, value);
                } else if self.peek() == Some('{') {
                    self.pos += 1;
                    let inner = self.parse_block_content();
                    map.insert(key, inner);
                }
            } else {
                self.pos += 1;
            }
        }

        Value::Object(map)
    }

    fn parse_value(&mut self) -> Value {
        self.skip_whitespace_and_comments();

        match self.peek() {
            Some('"') => self.parse_string(),
            Some('[') => self.parse_array(),
            Some('{') => {
                self.pos += 1;
                self.parse_block_content()
            }
            Some('t') | Some('f') => self.parse_bool(),
            Some('n') => self.parse_null(),
            Some('-') | Some('0'..='9') => self.parse_number(),
            _ => Value::Null,
        }
    }

    fn parse_string(&mut self) -> Value {
        if self.peek() != Some('"') {
            return Value::String(String::new());
        }

        self.pos += 1;
        let mut result = String::new();

        while self.pos < self.input.len() && self.peek() != Some('"') {
            if self.peek() == Some('\\') {
                self.pos += 1;
                if let Some(c) = self.peek() {
                    self.pos += 1;
                    match c {
                        'n' => result.push('\n'),
                        'r' => result.push('\r'),
                        't' => result.push('\t'),
                        '\\' => result.push('\\'),
                        '"' => result.push('"'),
                        _ => result.push(c),
                    }
                }
            } else if let Some(c) = self.peek() {
                result.push(c);
                self.pos += 1;
            }
        }

        if self.peek() == Some('"') {
            self.pos += 1;
        }

        Value::String(result)
    }

    fn parse_array(&mut self) -> Value {
        if self.peek() != Some('[') {
            return Value::Array(Vec::new());
        }

        self.pos += 1;
        let mut arr = Vec::new();

        loop {
            self.skip_whitespace_and_comments();

            if self.peek() == Some(']') {
                self.pos += 1;
                break;
            }

            arr.push(self.parse_value());

            self.skip_whitespace_and_comments();

            if self.peek() == Some(',') {
                self.pos += 1;
            } else if self.peek() == Some(']') {
                self.pos += 1;
                break;
            }
        }

        Value::Array(arr)
    }

    fn parse_bool(&mut self) -> Value {
        if self.match_word("true") {
            Value::Bool(true)
        } else if self.match_word("false") {
            Value::Bool(false)
        } else {
            Value::Null
        }
    }

    fn parse_null(&mut self) -> Value {
        if self.match_word("null") {
            Value::Null
        } else {
            Value::Null
        }
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;

        if self.peek() == Some('-') {
            self.pos += 1;
        }

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.pos += 1;
            } else {
                break;
            }
        }

        let mut is_float = false;

        if self.peek() == Some('.') {
            is_float = true;
            self.pos += 1;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }

        if self.peek() == Some('e') || self.peek() == Some('E') {
            is_float = true;
            self.pos += 1;
            if self.peek() == Some('+') || self.peek() == Some('-') {
                self.pos += 1;
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }

        let num_str = &self.input[start..self.pos];

        if is_float {
            if let Ok(f) = num_str.parse::<f64>() {
                return Value::Float(f);
            }
        } else {
            if let Ok(i) = num_str.parse::<i64>() {
                return Value::Integer(i);
            }
        }

        Value::Null
    }

    fn parse_identifier(&mut self) -> Option<String> {
        self.skip_whitespace_and_comments();

        if self.pos >= self.input.len() {
            return None;
        }

        let start = self.pos;
        let first = self.input.chars().nth(self.pos)?;

        if !first.is_alphabetic() && first != '_' {
            return None;
        }

        self.pos += 1;

        while self.pos < self.input.len() {
            let c = self.input.chars().nth(self.pos)?;
            if c.is_alphanumeric() || c == '_' || c == '-' {
                self.pos += 1;
            } else {
                break;
            }
        }

        Some(self.input[start..self.pos].to_string())
    }

    fn peek(&self) -> Option<char> {
        self.input.chars().nth(self.pos)
    }

    fn match_word(&mut self, word: &str) -> bool {
        if self.input[self.pos..].starts_with(word) {
            self.pos += word.len();
            true
        } else {
            false
        }
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
