                    in_string = true;
                    string_char = c;
                    current.push(c);
                }
                _ if in_string && c == string_char => {
                    in_string = false;
                    current.push(c);
                }
                '[' if !in_string => {
                    bracket_depth += 1;
                    current.push(c);
                }
                ']' if !in_string => {
                    bracket_depth -= 1;
                    current.push(c);
                }
                ',' if !in_string && bracket_depth == 0 => {
