use crate::ordered_map::OrderedMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Integer(i64),
    Float(f64),
    String(String),
    Array(Vec<Value>),
    Object(OrderedMap),
}

impl Value {
    pub fn to_json(&self, escape_html: bool, indent: bool) -> String {
        if indent {
            self.to_json_pretty(0, escape_html)
        } else {
            self.to_json_compact(escape_html)
        }
    }

    fn escape_json_string(s: &str, escape_html: bool) -> String {
        let mut result = String::new();
        for c in s.chars() {
            match c {
                '"' => result.push_str("\\\""),
                '\\' => result.push_str("\\\\"),
                '\n' => result.push_str("\\n"),
                '\r' => result.push_str("\\r"),
                '\t' => result.push_str("\\t"),
                '\u{0008}' => result.push_str("\\b"),
                '\u{000C}' => result.push_str("\\f"),
                '<' if escape_html => result.push_str("\\u003c"),
                '>' if escape_html => result.push_str("\\u003e"),
                '&' if escape_html => result.push_str("\\u0026"),
                _ => result.push(c),
            }
        }
        result
    }

    fn to_json_compact(&self, escape_html: bool) -> String {
        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        "\"Infinity\"".to_string()
                    } else {
                        "\"-Infinity\"".to_string()
                    }
                } else if f.is_nan() {
                    "\"NaN\"".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                let escaped = Self::escape_json_string(s, escape_html);
                format!("\"{}\"", escaped)
            }
            Value::Array(arr) => {
                let items: Vec<String> = arr.iter()
                    .map(|v| v.to_json_compact(escape_html))
                    .collect();
                format!("[{}]", items.join(","))
            }
            Value::Object(obj) => {
                let items: Vec<String> = obj.iter()
                    .map(|(k, v)| {
                        let key_json = format!("\"{}\"", Self::escape_json_string(k, escape_html));
                        format!("{}:{}", key_json, v.to_json_compact(escape_html))
                    })
                    .collect();
                format!("{{{}}}", items.join(","))
            }
        }
    }

    fn to_json_pretty(&self, depth: usize, escape_html: bool) -> String {
        let indent_str = "  ".repeat(depth);
        let next_indent_str = "  ".repeat(depth + 1);

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        "\"Infinity\"".to_string()
                    } else {
                        "\"-Infinity\"".to_string()
                    }
                } else if f.is_nan() {
                    "\"NaN\"".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                let escaped = Self::escape_json_string(s, escape_html);
                format!("\"{}\"", escaped)
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| format!("{}{}", next_indent_str, v.to_json_pretty(depth + 1, escape_html)))
                        .collect();
                    format!("[\n{}\n{}]", items.join(",\n"), indent_str)
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let items: Vec<String> = obj.iter()
                        .map(|(k, v)| {
                            let key_json = format!("\"{}\"", Self::escape_json_string(k, escape_html));
                            format!("{}{}: {}", next_indent_str, key_json, v.to_json_pretty(depth + 1, escape_html))
                        })
                        .collect();
                    format!("{{\n{}\n{}}}", items.join(",\n"), indent_str)
                }
            }
        }
    }

    pub fn to_yaml(&self) -> String {
        format!("{}\n", self.to_yaml_internal(0, true))
    }

    fn to_yaml_internal(&self, depth: usize, root: bool) -> String {
        let indent_str = "  ".repeat(depth);

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        ".inf".to_string()
                    } else {
                        "-.inf".to_string()
                    }
                } else if f.is_nan() {
                    ".nan".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                if s.contains('\n') || s.contains('"') || s.contains(':') {
                    format!("'{}'", s.replace('\'', "''"))
                } else {
                    s.clone()
                }
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| format!("{}  - {}", if depth > 0 { indent_str.as_str() } else { "" }, v.to_yaml_internal(depth + 1, false)))
                        .collect();
                    items.join("\n")
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let mut items = Vec::new();
                    for (k, v) in obj.iter() {
                        let key = if root {
                            k.clone()
                        } else {
                            format!("{}{}", indent_str, k)
                        };
                        match v {
                            Value::Object(_) | Value::Array(_) => {
                                items.push(format!("{}:\n{}", key, v.to_yaml_internal(depth + 1, false)));
                            }
                            _ => {
                                items.push(format!("{}: {}", key, v.to_yaml_internal(depth, false)));
                            }
                        }
                    }
                    items.join("\n")
                }
            }
        }
    }

    pub fn to_toml(&self, indent: bool, _no_convert_special: bool) -> String {
        self.to_toml_internal(0, indent)
    }

    fn to_toml_internal(&self, depth: usize, indent: bool) -> String {
        let indent_str = if indent { "  ".repeat(depth) } else { "".to_string() };

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => {
                if f.is_infinite() {
                    if f.is_sign_positive() {
                        "+inf".to_string()
                    } else {
                        "-inf".to_string()
                    }
                } else if f.is_nan() {
                    "nan".to_string()
                } else {
                    f.to_string()
                }
            }
            Value::String(s) => {
                format!("\"{}\"", 
                    s.replace('\\', "\\\\")
                     .replace('"', "\\\"")
                     .replace('\n', "\\n")
                     .replace('\r', "\\r")
                     .replace('\t', "\\t")
                )
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| v.to_toml_internal(depth + 1, indent))
                        .collect();
                    if indent && items.len() > 1 {
                        let next_indent = "  ".repeat(depth + 1);
                        format!("[\n{}{}\n{}]", next_indent, items.join(&format!(",\n{}", next_indent)), indent_str)
                    } else {
                        format!("[{}]", items.join(", "))
                    }
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let mut items = Vec::new();
                    for (k, v) in obj.iter() {
                        items.push(format!("{} = {}", k, v.to_toml_internal(depth + 1, indent)));
                    }
                    if indent && depth > 0 {
                        let next_indent = "  ".repeat(depth);
                        items.join(&format!("\n{}", next_indent))
                    } else {
                        items.join("\n")
                    }
                }
            }
        }
    }

    pub fn to_hcl(&self) -> String {
        self.to_hcl_internal(0)
    }

    fn to_hcl_internal(&self, depth: usize) -> String {
        let indent_str = "  ".repeat(depth);
        let next_indent = "  ".repeat(depth + 1);

        match self {
            Value::Null => "null".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => f.to_string(),
            Value::String(s) => {
                format!("\"{}\"", 
                    s.replace('\\', "\\\\")
                     .replace('"', "\\\"")
                     .replace('\n', "\\n")
                     .replace('\r', "\\r")
                     .replace('\t', "\\t")
                )
            }
            Value::Array(arr) => {
                if arr.is_empty() {
                    "[]".to_string()
                } else {
                    let items: Vec<String> = arr.iter()
                        .map(|v| format!("{}{}", next_indent, v.to_hcl_internal(depth + 1)))
                        .collect();
                    format!("[\n{}\n{}]", items.join(",\n"), indent_str)
                }
            }
            Value::Object(obj) => {
                if obj.is_empty() {
                    "{}".to_string()
                } else {
                    let items: Vec<String> = obj.iter()
                        .map(|(k, v)| {
                            format!("{}{} = {}", next_indent, k, v.to_hcl_internal(depth + 1))
                        })
                        .collect();
                    format!("{{\n{}\n{}}}", items.join("\n"), indent_str)
                }
            }
        }
    }
}
