mod yaml_parser;
mod toml_parser;
mod hcl_parser;
mod value;
mod ordered_map;

use value::Value;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse arguments
    let mut from_format = 'y'; // default: YAML
    let mut to_format = 'j';   // default: JSON
    let mut escape_html = false;
    let mut indent = false;
    let mut no_convert_special = false;
    let mut parse_keys = false;
    let mut help = false;
    let mut version = false;

    for arg in &args[1..] {
        if arg == "-h" || arg == "--help" {
            help = true;
        } else if arg == "-v" || arg == "--version" {
            version = true;
        } else if arg.starts_with('-') && arg.len() > 1 {
            let flags = &arg[1..];

            // Handle two-character conversions like -yj, -yt, etc.
            // Check first if this is a conversion pattern
            let mut is_conversion = false;
            if flags.len() >= 2 {
                let first = flags.chars().next().unwrap();
                let second = flags.chars().nth(1).unwrap();

                if (first == 'y' || first == 't' || first == 'j' || first == 'c') && 
                   (second == 'y' || second == 't' || second == 'j' || second == 'c' || second == 'r') {
                    from_format = first;
                    to_format = if second == 'r' { 'y' } else { second };
                    is_conversion = true;
                }
            }

            // Handle single character flags (only if not a conversion)
            if !is_conversion {
                for c in flags.chars() {
                    match c {
                        'y' => { from_format = 'y'; to_format = 'j'; },
                        't' => { from_format = 't'; to_format = 'j'; },
                        'j' => { to_format = 'j'; },
                        'c' => { to_format = 'c'; },
                        'r' => { from_format = 'j'; to_format = 'y'; },
                        'n' => no_convert_special = true,
                        'e' => escape_html = true,
                        'i' => indent = true,
                        'k' => parse_keys = true,
                        'h' => help = true,
                        'v' => version = true,
                        _ => {}
                    }
                }
            }
        }
    }

    if help {
        print_help();
        return;
    }

    if version {
        println!("v0.0.0");
        return;
    }

    // Read from stdin
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).expect("Failed to read from stdin");

    // Parse input
    let value = parse_input(&input, from_format, parse_keys, no_convert_special);

    // Convert to output format
    let output = convert_value(&value, to_format, escape_html, indent, no_convert_special);
    print!("{}", output);
}

fn print_help() {
    println!("Usage: yj [-][ytjcrneikhv]");
    println!();
    println!("Convert between YAML, TOML, JSON, and HCL.");
    println!("Preserves map order.");
    println!();
    println!("-x[x]  Convert using stdin. Valid options:");
    println!("          -yj, -y = YAML to JSON (default)");
    println!("          -yy     = YAML to YAML");
    println!("          -yt     = YAML to TOML");
    println!("          -yc     = YAML to HCL");
    println!("          -tj, -t = TOML to JSON");
    println!("          -ty     = TOML to YAML");
    println!("          -tt     = TOML to TOML");
    println!("          -tc     = TOML to HCL");
    println!("          -jj     = JSON to JSON");
    println!("          -jy, -r = JSON to YAML");
    println!("          -jt     = JSON to TOML");
    println!("          -jc     = JSON to HCL");
    println!("          -cy     = HCL to YAML");
    println!("          -ct     = HCL to TOML");
    println!("          -cj, -c = HCL to JSON");
    println!("          -cc     = HCL to HCL");
    println!("-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)");
    println!("-e     Escape HTML (JSON out only)");
    println!("-i     Indent output (JSON or TOML out only)");
    println!("-k     Attempt to parse keys as objects or numeric types (YAML out only)");
    println!("-h     Show this help message");
    println!("-v     Show version");
    println!();
}

fn parse_input(input: &str, format: char, parse_keys: bool, no_convert_special: bool) -> Value {
    match format {
        'y' => yaml_parser::parse(input, parse_keys, no_convert_special),
        't' => toml_parser::parse(input, no_convert_special),
        'j' => json_parser::parse(input),
        'c' => hcl_parser::parse(input),
        _ => Value::Null,
    }
}

fn convert_value(
    value: &Value,
    to_format: char,
    escape_html: bool,
    indent: bool,
    no_convert_special: bool,
) -> String {
    match to_format {
        'j' => value.to_json(escape_html, indent, no_convert_special),
        'y' => value.to_yaml(no_convert_special),
        't' => value.to_toml(indent),
        'c' => value.to_hcl(),
        _ => String::new(),
    }
}
