pub fn parse(input: &str, parse_keys: bool, _no_convert_special: bool) -> Value {
    let lines: Vec<&str> = input.lines().collect();
    let mut parser = YamlParser::new(&lines, parse_keys);
    parser.parse()
}

struct YamlParser<'a> {
    lines: &'a [&'a str],
    pos: usize,
    parse_keys: bool,
}

