        YamlParser {
            lines,
            pos: 0,
            parse_keys,
        }
    }

    fn parse(&mut self) -> Value {
        self.skip_empty_lines();
        if self.pos >= self.lines.len() {
            return Value::Null;
        }

        let indent = self.get_indent(self.pos);
        self.parse_node(indent)
    }

    fn parse_node(&mut self, parent_indent: usize) -> Value {
        self.skip_empty_lines();
        if self.pos >= self.lines.len() {
            return Value::Null;
        }

        let line = self.lines[self.pos];
        let indent = self.get_indent(self.pos);

        if indent < parent_indent {
            return Value::Null;
        }

        let content = line.trim();

        // Check if this is a list item
        if content.starts_with("- ") {
            return self.parse_list(parent_indent);
        }

        // Check if this is a mapping
        if content.contains(':') && !content.starts_with('#') {
            return self.parse_mapping(parent_indent);
        }

        // Parse as a scalar value
        self.pos += 1;
        self.parse_scalar(content)
    }

    fn parse_list(&mut self, parent_indent: usize) -> Value {
        let mut arr = Vec::new();

        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            let indent = self.get_indent(self.pos);

            if indent < parent_indent {
                break;
            }

            let content = line.trim();
            if content.starts_with("- ") {
                self.pos += 1;
                let item_content = &content[2..];

                if item_content.contains(':') {
                    let mut item_map = OrderedMap::new();
                    let key_val: Vec<&str> = item_content.splitn(2, ':').collect();
                    if key_val.len() == 2 {
                        let key = key_val[0].trim();
                        let value = self.parse_scalar(key_val[1].trim());
                        item_map.insert(key.to_string(), value);
                    }

