                    while self.pos < self.lines.len() {
                        let next_line = self.lines[self.pos];
                        let next_indent = self.get_indent(self.pos);
                        let next_content = next_line.trim();

                        if next_indent <= parent_indent {
                            break;
                        }

                        if !next_content.starts_with("- ") && next_content.contains(':') {
                            self.pos += 1;
                            let key_val: Vec<&str> = next_content.splitn(2, ':').collect();
                            if key_val.len() == 2 {
                                let key = key_val[0].trim();
                                let value = self.parse_scalar(key_val[1].trim());
                                item_map.insert(key.to_string(), value);
                            }
                        } else {
                            break;
                        }
                    }

                    arr.push(Value::Object(item_map));
                } else {
                    arr.push(self.parse_scalar(item_content));
                }
            } else if indent > parent_indent {
                break;
            } else {
                break;
            }
        }

