use crate::value::Value;
use crate::ordered_map::OrderedMap;

pub fn parse(input: &str, _no_convert_special: bool) -> Value {
    let lines: Vec<&str> = input.lines().collect();
    let mut parser = TomlParser::new(&lines);
    parser.parse()
}

struct TomlParser<'a> {
    lines: &'a [&'a str],
    pos: usize,
}

impl<'a> TomlParser<'a> {
    fn new(lines: &'a [&'a str]) -> Self {
        TomlParser { lines, pos: 0 }
    }

    fn parse(&mut self) -> Value {
        let mut root = OrderedMap::new();

        while self.pos < self.lines.len() {
            let line = self.lines[self.pos];
            let trimmed = line.trim();
            self.pos += 1;

            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }

            if trimmed.starts_with('[') {
                // Table section - skip for now
                continue;
            }

            if let Some(eq_idx) = trimmed.find('=') {
                let key = trimmed[..eq_idx].trim();
                let value_str = trimmed[eq_idx + 1..].trim();
                let value = self.parse_value(value_str);
                root.insert(key.to_string(), value);
            }
        }

        Value::Object(root)
    }

    fn parse_value(&mut self, value_str: &str) -> Value {
        let trimmed = value_str.trim();

        if trimmed.is_empty() {
            return Value::Null;
        }

        // String
        if (trimmed.starts_with('"') && trimmed.ends_with('"')) ||
           (trimmed.starts_with('\'') && trimmed.ends_with('\'')) {
            let quote = trimmed.chars().next().unwrap();
            let unquoted = &trimmed[1..trimmed.len()-1];
            if quote == '"' {
                return Value::String(self.unescape_string(unquoted));
            } else {
                return Value::String(unquoted.to_string());
            }
        }

        // Boolean
        if trimmed == "true" {
            return Value::Bool(true);
        }
        if trimmed == "false" {
            return Value::Bool(false);
        }

        // Special floats
        if trimmed == "inf" || trimmed == "+inf" {
            return Value::Float(f64::INFINITY);
        }
        if trimmed == "-inf" {
            return Value::Float(f64::NEG_INFINITY);
        }
        if trimmed == "nan" {
            return Value::Float(f64::NAN);
        }

        // Array
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            return self.parse_array(&trimmed[1..trimmed.len()-1]);
        }

        // Inline table
        if trimmed.starts_with('{') && trimmed.ends_with('}') {
            return self.parse_inline_table(&trimmed[1..trimmed.len()-1]);
        }

        // Number
        if let Ok(i) = trimmed.parse::<i64>() {
            return Value::Integer(i);
        }

        if let Ok(f) = trimmed.parse::<f64>() {
            return Value::Float(f);
        }

        Value::String(trimmed.to_string())
    }

    fn parse_array(&mut self, content: &str) -> Value {
        let mut arr = Vec::new();
        let mut current = String::new();
        let mut in_string = false;
        let mut string_char = ' ';
        let mut bracket_depth = 0;

        for c in content.chars() {
            match c {
                '"' | '\'' if !in_string => {
                    in_string = true;
                    string_char = c;
                    current.push(c);
                }
                _ if in_string && c == string_char => {
                    in_string = false;
                    current.push(c);
                }
                '[' if !in_string => {
                    bracket_depth += 1;
                    current.push(c);
                }
                ']' if !in_string => {
                    bracket_depth -= 1;
                    current.push(c);
                }
                ',' if !in_string && bracket_depth == 0 => {
                    let trimmed = current.trim();
                    if !trimmed.is_empty() {
                        arr.push(self.parse_value(trimmed));
                    }
                    current.clear();
                }
                _ => current.push(c),
            }
        }

        let trimmed = current.trim();
        if !trimmed.is_empty() {
            arr.push(self.parse_value(trimmed));
        }

        Value::Array(arr)
    }

    fn parse_inline_table(&mut self, content: &str) -> Value {
        let mut map = OrderedMap::new();
        let mut current_key = String::new();
        let mut current_value = String::new();
        let mut in_string = false;
        let mut string_char = ' ';
        let mut in_value = false;

        for c in content.chars() {
            match c {
                '"' | '\'' if !in_string => {
                    in_string = true;
                    string_char = c;
                    if in_value {
                        current_value.push(c);
                    } else {
                        current_key.push(c);
                    }
                }
                _ if in_string && c == string_char => {
                    in_string = false;
                    if in_value {
                        current_value.push(c);
                    } else {
                        current_key.push(c);
                    }
                }
                '=' if !in_string && !in_value => {
                    in_value = true;
                }
                ',' if !in_string && in_value => {
                    let key = current_key.trim().to_string();
                    let value = self.parse_value(current_value.trim());
                    map.insert(key, value);
                    current_key.clear();
                    current_value.clear();
                    in_value = false;
                }
                _ => {
                    if in_value {
                        current_value.push(c);
                    } else {
                        current_key.push(c);
                    }
                }
            }
        }

        if !current_key.is_empty() && in_value {
            let key = current_key.trim().to_string();
            let value = self.parse_value(current_value.trim());
            map.insert(key, value);
        }

        Value::Object(map)
    }

    fn unescape_string(&self, s: &str) -> String {
        let mut result = String::new();
        let mut chars = s.chars().peekable();

        while let Some(c) = chars.next() {
            if c == '\\' {
                if let Some(&next) = chars.peek() {
                    chars.next();
                    match next {
                        'n' => result.push('\n'),
                        'r' => result.push('\r'),
                        't' => result.push('\t'),
                        '\\' => result.push('\\'),
                        '"' => result.push('"'),
                        'b' => result.push('\u{0008}'),
                        'f' => result.push('\u{000c}'),
                        _ => {
                            result.push('\\');
                            result.push(next);
                        }
                    }
                } else {
                    result.push(c);
                }
            } else {
                result.push(c);
            }
        }

        result
    }
}
